result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "graphql-dataloader/app/dataloader.py", "content": """"A minimal per-request batching DataLoader.

Keys requested during the same event-loop tick are accumulated; the first
load() schedules a dispatch via ``loop.call_soon`` so that every sibling
resolver (graphql-core resolves list items concurrently) can enqueue its key
before exactly ONE batched ``batch_load_fn(keys)`` call happens.

Values are memoized per key for the lifetime of the loader instance, which
is created once per GraphQL request (see app.schema.build_context).
"""

from __future__ import annotations

import asyncio
from typing import Any, Awaitable, Callable, Dict, List, Sequence, Tuple

# batch_load_fn takes a list of keys and returns an iterable of (key, value)
# pairs (sync or awaitable).
BatchLoadFn = Callable[[Sequence[Any]], Any]


class DataLoader:
    def __init__(self, batch_load_fn: BatchLoadFn) -> None:
        self.batch_load_fn = batch_load_fn
        self._cache: Dict[Any, Any] = {}          # key -> resolved value or pending Future
        self._queue: List[Tuple[Any, asyncio.Future]] = []
        self._scheduled = False

    # ------------------------------------------------------------------ api
    def load(self, key: Any) -> asyncio.Future:
        """Return a Future for ``key``, batching identical-tick requests."""
        try:
            cached = self._cache[key]
        except KeyError:
            pass
        else:
            return cached  # already resolved this request, or already queued

        loop = asyncio.get_running_loop()
        future: asyncio.Future = loop.create_future()
        self._cache[key] = future
        self._queue.append((key, future))
        if not self._scheduled:
            self._scheduled = True
            loop.call_soon(self._dispatch)
        return future

    def prime(self, key: Any, value: Any) -> None:
        """Pre-populate the cache (useful for prefetch patterns)."""
        self._cache[key] = value

    # ------------------------------------------------------------ internals
    def _dispatch(self) -> None:
        self._scheduled = False
        batch, self._queue = self._queue, []
        if not batch:
            return

        keys = [key for key, _ in batch]
        try:
            outcome = self.batch_load_fn(keys)
            if asyncio.iscoroutine(outcome) or isinstance(outcome, Awaitable):
                # async batch fn: chain resolution onto its completion
                asyncio.ensure_future(self._resolve_async(batch, outcome))
            else:
                self._resolve(batch, dict(outcome))
        except Exception as exc:  # surface errors to every waiter
            for _key, future in batch:
                if not future.done():
                    future.set_exception(exc)

    def _resolve(self, batch, results: Dict[Any, Any]) -> None:
        for key, future in batch:
            if future.done():
                continue
            try:
                future.set_result(results[key])
            except KeyError as exc:
                future.set_exception(
                    KeyError(f"DataLoader batch_load_fn returned no value for key {key!r}")
                ) from exc

    async def _resolve_async(self, batch, coro: Awaitable) -> None:
        try:
            self._resolve(batch, dict(await coro))
        except Exception as exc:
            for _key, future in batch:
                if not future.done():
                    future.set_exception(exc)
"})
