result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "graphql-dataloader/app/schema.py", "content": """"Ariadne schema over SQLite with switchable author resolution strategies.

- naive:   one SELECT per book   -> 1 + N queries (N = number of books)
- batched: per-request DataLoader -> 2 queries regardless of book count
"""

from __future__ import annotations

from typing import Any, Dict

from ariadne import ObjectType, QueryType, make_executable_schema

from .dataloader import DataLoader

type_defs = """
type Query {
  books: [Book!]!
}

type Book {
  title: String!
  author: Author!
}

type Author {
  name: String!
}
"""

query = QueryType()
book = ObjectType("Book")


@query.field("books")
def resolve_books(_, info):
    db = info.context["db"]
    rows = db.execute("SELECT id, title, author_id FROM books ORDER BY id").fetchall()
    return [{"id": r[0], "title": r[1], "author_id": r[2]} for r in rows]


@book.field("author")
async def resolve_author(book, info):
    ctx: Dict[str, Any] = info.context
    loader: DataLoader | None = ctx.get("author_loader")
    if loader is not None:
        # Batched path: future is fulfilled by ONE "SELECT ... WHERE id IN (...)"
        return await loader.load(book["author_id"])
    # Naive path: one round trip per book
    db = ctx["db"]
    name = db.execute(
        "SELECT name FROM authors WHERE id = ?", (book["author_id"],)
    ).fetchone()[0]
    return {"name": name}


def make_author_loader(db) -> DataLoader:
    def batch_load(author_ids):
        placeholders = ",".join("?" for _ in author_ids)
        rows = db.execute(
            f"SELECT id, name FROM authors WHERE id IN ({placeholders})",
            tuple(sorted(set(author_ids))),
        ).fetchall()
        by_id = {row[0]: {"name": row[1]} for row in rows}
        return [(aid, by_id[aid]) for aid in author_ids]

    return DataLoader(batch_load)


def build_context(db, *, batched: bool) -> Dict[str, Any]:
    """One context == one request == one DataLoader instance."""
    ctx: Dict[str, Any] = {"db": db}
    if batched:
        ctx["author_loader"] = make_author_loader(db)
    return ctx


schema = make_executable_schema(type_defs, query, book)
