from __future__ import annotations

import sqlite3
from typing import Any, List, Sequence, Tuple


class CountingConnection:
    """Thin proxy over sqlite3.Connection that counts every execute() call."""

    def __init__(self, conn: sqlite3.Connection) -> None:
        self._conn = conn
        self.query_count = 0

    # used by resolvers -----------------------------------------------------
    def execute(self, sql: str, params: Sequence[Any] = ()) -> sqlite3.Cursor:
        self.query_count += 1
        return self._conn.execute(sql, tuple(params))

    # test helpers ----------------------------------------------------------
    def reset_counter(self) -> None:
        self.query_count = 0

    @property
    def queries(self) -> int:
        return self.query_count

    def __getattr__(self, name: str) -> Any:  # delegate the rest
        return getattr(self._conn, name)


def make_counting_db(path: str = ":memory:", books: int = 40, authors: int = 8) -> CountingConnection:
    conn = sqlite3.connect(path)
    conn.execute("CREATE TABLE authors (id INTEGER PRIMARY KEY, name TEXT NOT NULL)")
    conn.execute("CREATE TABLE books (id INTEGER PRIMARY KEY, title TEXT NOT NULL, author_id INTEGER NOT NULL REFERENCES authors(id))")
    conn.executemany(
        "INSERT INTO authors (id, name) VALUES (?, ?)",
        [(i, f"Author {chr(ord('A') + i)}") for i in range(authors)],
    )
    conn.executemany(
        "INSERT INTO books (id, title, author_id) VALUES (?, ?, ?)",
        [(i, f"Book #{i:02d}", i % authors) for i in range(books)],
    )
    conn.commit()
    return CountingConnection(conn)
